/**
 * @param {number} n
 * @return {number}
 */
var bitwiseComplement = function(n) {
    const bin = n.toString(2);
    const last = bin.length - 1;
    let res = 0;

    for (let i = last; i >= 0; i--) {
        if (bin[i] === '0') {
            res += 1 << (last - i);
        }
    }

    return res;
};
